// Data Cleaner v5 - Enterprise Hardened Version
// Google Sheets Compatible + Stable Client + Stable Audit ID

const items = $input.all();

// ============================================================
// HELPER FUNCTIONS
// ============================================================

function getField(obj, ...possibleNames) {
  for (const name of possibleNames) {
    if (obj[name] !== undefined) return obj[name];
    const lower = name.toLowerCase();
    for (const key of Object.keys(obj)) {
      if (key.toLowerCase() === lower) return obj[key];
    }
  }
  return null;
}

function safeGetNode(nodeName) {
  try {
    const node = $(nodeName);
    if (node && node.first) return node.first().json;
  } catch {}
  return null;
}

function safeNumber(val, fallback = 0) {
  const n = parseFloat(val);
  return isNaN(n) ? fallback : n;
}

// ============================================================
// SAFE CLIENT + AUDIT RESOLUTION
// ============================================================

const dynamicCfg = safeGetNode('Optional - Map Queue Row to Config') || {};
const clientConfig = safeGetNode('Set Client Config') || {};
const baseInput = $input.first()?.json || {};

const resolvedClient =
  clientConfig.client_name ||
  dynamicCfg.client_name ||
  baseInput.client_name ||
  baseInput.Client_Name ||
  "Unknown Client";

const resolvedAuditId =
  clientConfig.audit_id ||
  dynamicCfg.audit_id ||
  baseInput.audit_id ||
  baseInput.Audit_ID ||
  null; // Only generate if truly missing

const auditIdFinal = resolvedAuditId || `AUDIT_${Date.now()}`;
const auditTimestamp =
  clientConfig.audit_timestamp ||
  dynamicCfg.audit_timestamp ||
  new Date().toISOString();

// ============================================================
// INITIAL STRUCTURE
// ============================================================

const currentModelData = {
  client_name: resolvedClient,
  audit_id: auditIdFinal,
  audit_timestamp: auditTimestamp,
  org_structure: [],
  tools: [],
  processes: [],
  kpis: {},
  raw_documents: [],
  data_quality: 0
};

let raciCount = 0;
let toolCount = 0;
let kpiCount = 0;

// ============================================================
// PROCESS INPUT ROWS
// ============================================================

for (const item of items) {
  const data = item.json || {};

  const hasRaciSignal =
    getField(data, 'Process/Task', 'Process', 'Task') &&
    getField(data, 'Responsible', 'R');

  const hasToolSignal =
    getField(data, 'ToolName', 'Tool Name', 'Tool') &&
    getField(data, 'Purpose', 'Description');

  const metric = getField(data, 'Metric', 'KPI', 'Name');
  const value = getField(data, 'Value', 'Vale', 'Amount', 'Score');

  // ---- RACI ----
  if (hasRaciSignal) {
    currentModelData.org_structure.push({
      type: 'raci_matrix',
      process: getField(data, 'Process/Task', 'Process', 'Task') || '',
      responsible: getField(data, 'Responsible', 'R') || '',
      accountable: getField(data, 'Accountable', 'A') || '',
      consulted: getField(data, 'Consulted', 'C') || '',
      informed: getField(data, 'Informed', 'I') || '',
      team: getField(data, 'Team', 'Department') || '',
      tool_used: getField(data, 'Tool Used', 'Tool', 'Tools') || '',
      frequency: getField(data, 'Frequency') || '',
      manual_pct: safeNumber(getField(data, 'Manual %', 'Manual')),
      source: 'google_sheets'
    });
    raciCount++;
    continue;
  }

  // ---- TOOLS ----
  if (hasToolSignal) {
    currentModelData.tools.push({
      name: getField(data, 'ToolName', 'Tool Name', 'Tool') || '',
      purpose: getField(data, 'Purpose', 'Description', 'Use') || '',
      users: safeNumber(getField(data, 'UserCount', 'User Count', 'Users')),
      overlap_score: safeNumber(getField(data, 'OverlapScore', 'Overlap Score')),
      annual_cost: safeNumber(getField(data, 'AnnualCost', 'Annual Cost', 'Cost')),
      source: 'google_sheets'
    });
    toolCount++;
    continue;
  }

  // ---- KPIs ----
  if (metric && value !== null) {
    const metricLower = String(metric).toLowerCase();
    const numValue = safeNumber(value);

    if (metricLower.includes('turnaround')) {
      currentModelData.kpis.turnaround_time_avg = numValue;
    } else if (metricLower.includes('utilization')) {
      currentModelData.kpis.fte_utilization = numValue;
    } else if (metricLower.includes('cost')) {
      currentModelData.kpis.cost_per_asset = numValue;
    } else if (metricLower.includes('error')) {
      currentModelData.kpis.error_rate = numValue;
    } else if (metricLower.includes('volume')) {
      currentModelData.kpis.volume_per_month = numValue;
    }

    kpiCount++;
    continue;
  }

  // ---- DOCUMENTS ----
  if (data.mimeType || item.binary) {
    currentModelData.raw_documents.push({
      name: data.name || 'Document',
      type: data.mimeType || 'unknown',
      source: 'google_drive'
    });
  }
}

// ============================================================
// FALLBACK ONLY IF TRULY EMPTY
// ============================================================

if (raciCount === 0 && currentModelData.org_structure.length === 0) {
  currentModelData.org_structure = [];
}

if (toolCount === 0 && currentModelData.tools.length === 0) {
  currentModelData.tools = [];
}

if (Object.keys(currentModelData.kpis).length === 0) {
  currentModelData.kpis = {};
}

// ============================================================
// DATA QUALITY SCORE
// ============================================================

const dataQuality = Math.round(
  (raciCount > 0 ? 33 : 0) +
  (toolCount > 0 ? 33 : 0) +
  (kpiCount > 0 ? 34 : 0)
);

currentModelData.data_quality = dataQuality;

// ============================================================
// LOGGING
// ============================================================

console.log('Data Cleaner v5 Summary');
console.log('- Client:', resolvedClient);
console.log('- Audit ID:', auditIdFinal);
console.log('- RACI rows:', raciCount);
console.log('- Tools:', toolCount);
console.log('- KPIs:', kpiCount);
console.log('- Data quality:', dataQuality + '%');

// ============================================================
// RETURN SINGLE ITEM
// ============================================================

return [{ json: currentModelData }];

