function s(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  try { return JSON.stringify(v); } catch (e) { return String(v); }
}

function stripFences(t) {
  return String(t || '')
    .replace(/```mermaid\s*/gi, '')
    .replace(/```json\s*/gi, '')
    .replace(/```/g, '')
    .trim();
}

function wrapMermaid(diagram) {
  const body = stripFences(diagram);
  return '```mermaid\n' + body + '\n```';
}

function makeArchitecture(auditId, clientName) {
  const id = auditId || 'unknown';
  const cn = clientName || 'unknown';
  return [
    'flowchart TB',
    '  subgraph Intake',
    '    A["Brief intake"] --> B["Triage and validate"]',
    '  end',
    '  subgraph Design',
    '    B --> C["Operating model blueprint"]',
    '    C --> D["RACI and governance"]',
    '  end',
    '  subgraph Output',
    '    D --> E["Diagrams and reports"]',
    '    E --> F["Write to Google Sheets"]',
    '  end',
    '  %% audit_id: ' + id,
    '  %% client_name: ' + cn
  ].join('\n');
}

function makeRoadmap(auditId, clientName) {
  const id = auditId || 'unknown';
  const cn = clientName || 'unknown';
  return [
    'gantt',
    '  title Operating Model Delivery Roadmap',
    '  dateFormat  YYYY-MM-DD',
    '  axisFormat  %d %b',
    '  section Foundation',
    '  Data contract and schema      :a1, 2026-01-01, 10d',
    '  Sheet upsert and dedupe       :a2, after a1, 7d',
    '  section Build',
    '  Executive summary and RACI    :b1, after a2, 10d',
    '  Diagrams and reporting pack   :b2, after b1, 7d',
    '  section Scale',
    '  Performance tuning            :c1, after b2, 7d',
    '  Governance and QA             :c2, after c1, 7d',
    '  %% audit_id: ' + id,
    '  %% client_name: ' + cn
  ].join('\n');
}

function makeProcessFlow(auditId, clientName) {
  const id = auditId || 'unknown';
  const cn = clientName || 'unknown';
  return [
    'flowchart LR',
    '  I["Inputs"] --> P["Process"] --> O["Outputs"]',
    '  subgraph Inputs',
    '    I1["Client config"]',
    '    I2["Audit data"]',
    '  end',
    '  subgraph Process',
    '    P1["Generate operating model"]',
    '    P2["Generate executive summary"]',
    '    P3["Generate RACI"]',
    '    P4["Generate diagrams"]',
    '    P5["Write to Sheets"]',
    '  end',
    '  subgraph Outputs',
    '    O1["Operating model JSON"]',
    '    O2["Executive summary"]',
    '    O3["RACI"]',
    '    O4["Mermaid diagrams"]',
    '  end',
    '  I1 --> P1',
    '  I2 --> P1',
    '  P1 --> P2 --> P3 --> P4 --> P5',
    '  P5 --> O1',
    '  P5 --> O2',
    '  P5 --> O3',
    '  P5 --> O4',
    '  %% audit_id: ' + id,
    '  %% client_name: ' + cn
  ].join('\n');
}

function makeTechStack(auditId, clientName) {
  const id = auditId || 'unknown';
  const cn = clientName || 'unknown';
  return [
    'flowchart TB',
    '  U["Users and SMEs"] --> N["n8n workflow"]',
    '  N --> L["LLM calls"]',
    '  N --> S["Google Sheets"]',
    '  L --> R["Model outputs"]',
    '  S --> R',
    '  subgraph LLM',
    '    L1["GPT model"]',
    '  end',
    '  subgraph Storage',
    '    S1["Sheets tabs as store"]',
    '  end',
    '  %% audit_id: ' + id,
    '  %% client_name: ' + cn
  ].join('\n');
}

const inputItem = $input.first().json || {};

const audit_id = s(inputItem.audit_id || inputItem.auditId || inputItem.audit || '').trim() || 'unknown';
const client_name = s(inputItem.client_name || inputItem.clientName || inputItem.client || '').trim() || 'unknown';
const created_at = new Date().toISOString();
const render_hint = 'mermaid';

const diagrams = [
  { diagram_type: 'architecture', mermaid_code: wrapMermaid(makeArchitecture(audit_id, client_name)) },
  { diagram_type: 'roadmap', mermaid_code: wrapMermaid(makeRoadmap(audit_id, client_name)) },
  { diagram_type: 'process_flow', mermaid_code: wrapMermaid(makeProcessFlow(audit_id, client_name)) },
  { diagram_type: 'tech_stack', mermaid_code: wrapMermaid(makeTechStack(audit_id, client_name)) },
];

return diagrams.map(d => {
  return {
    json: {
      row_key: client_name + '|' + audit_id + '|' + d.diagram_type,
      audit_id,
      diagram_type: d.diagram_type,
      mermaid_code: d.mermaid_code,
      render_hint,
      created_at,
    }
  };
});

