// Financial Model Deep-Dive - CFO-Grade Financial Analysis
// Hardened Version - Stable Client + Audit Resolution

// ============================================================
// SECTION 1: HELPER FUNCTIONS
// ============================================================

function parseAIResponse(content) {
  if (!content) return {};
  let cleaned = content.trim();

  if (cleaned.startsWith('```json')) cleaned = cleaned.slice(7);
  else if (cleaned.startsWith('```')) cleaned = cleaned.slice(3);
  if (cleaned.endsWith('```')) cleaned = cleaned.slice(0, -3);

  cleaned = cleaned.trim();

  try {
    return JSON.parse(cleaned);
  } catch {
    return {};
  }
}

function safeGetNode(nodeName) {
  try {
    const node = $(nodeName);
    if (node && node.first) return node.first().json;
  } catch {}
  return null;
}

// ============================================================
// SECTION 2: SAFE INPUT RESOLUTION
// ============================================================

const baseInput = $input.first()?.json || {};

const dynamicCfg = safeGetNode('Optional - Map Queue Row to Config') || {};
const clientConfig = safeGetNode('Set Client Config') || {};
const cleanedData = safeGetNode('2.1 Data Cleaner') || baseInput || {};
const ineffNode = safeGetNode('2.2 Inefficiency Scorer - GPT-4o');
const aiNode = safeGetNode('2.3 Map AI and Automation Opportunities');
const benchmarkData = safeGetNode('2.4b Benchmark Comparator') || {};

let inefficiencyData = {};
let aiRecommendations = {};

if (ineffNode?.message?.content) {
  inefficiencyData = parseAIResponse(ineffNode.message.content);
}

if (aiNode?.message?.content) {
  aiRecommendations = parseAIResponse(aiNode.message.content);
}

// ---- Hardened Client + Audit Resolution ----

const resolvedClient =
  clientConfig.client_name ||
  dynamicCfg.client_name ||
  cleanedData.client_name ||
  baseInput.client_name ||
  baseInput.Client_Name ||
  "Unknown Client";

const resolvedAuditId =
  cleanedData.audit_id ||
  clientConfig.audit_id ||
  dynamicCfg.audit_id ||
  baseInput.audit_id ||
  baseInput.Audit_ID ||
  `AUDIT_${Date.now()}`;

// ============================================================
// SECTION 3: CONFIGURATION
// ============================================================

const cfgNode = safeGetNode('Set Client Config') || dynamicCfg || clientConfig || {};
const config = {
  avg_fte_cost: Number(cfgNode.avg_fte_cost || 85000),
  hours_per_fte_year: Number(cfgNode.hours_per_fte_year || 1800),
  software_license_annual: Number(cfgNode.software_license_annual || 25000),
  integration_cost_per_system: Number(cfgNode.integration_cost_per_system || 15000),
  training_cost_per_fte: Number(cfgNode.training_cost_per_fte || 2500),
  change_management_pct: Number(cfgNode.change_management_pct || 0.15),
  discount_rate: Number(cfgNode.discount_rate || 0.10),
  tax_rate: 0.25,
  inflation_rate: 0.03,
  implementation_risk_buffer: Number(cfgNode.implementation_risk_buffer || 0.20),
  benefit_realization_factor: Number(cfgNode.benefit_realization_factor || 0.85),
  analysis_years: Number(cfgNode.analysis_years || 5),
  market_count: Number(cfgNode.market_count || 5)
};

// ============================================================
// SECTION 4: TCO CALCULATION
// ============================================================

function calculateTCO(scenario) {

  const complexity_multiplier =
    scenario === 'cautious' ? 0.5 :
    scenario === 'aggressive' ? 1.8 :
    1.0;

  const recommendations = aiRecommendations.recommendations || [];

  const simpleCount = recommendations.filter(r => r.implementation_complexity === 'Simple').length;
  const moderateCount = recommendations.filter(r => r.implementation_complexity === 'Moderate').length;
  const complexCount = recommendations.filter(r => r.implementation_complexity === 'Complex').length;

  const implementation =
    (2 + Math.floor(complexCount / 2)) * config.software_license_annual * complexity_multiplier +
    (simpleCount * 5000 + moderateCount * 15000 + complexCount * 40000) * complexity_multiplier +
    20000 * complexity_multiplier;

  const contingency = implementation * config.implementation_risk_buffer;

  const implementationTotal = Math.round(implementation + contingency);

  const recurring = Math.round(
    (implementationTotal * 0.3) +
    config.avg_fte_cost * (scenario === 'aggressive' ? 1.5 : scenario === 'hybrid' ? 1 : 0.5)
  );

  return {
    implementation_total: implementationTotal,
    annual_recurring: recurring,
    five_year_total: implementationTotal + (recurring * config.analysis_years)
  };
}

// ============================================================
// SECTION 5: BENEFIT CALCULATION
// ============================================================

function calculateBenefits(scenario) {

  const scenario_factor =
    scenario === 'cautious' ? 0.4 :
    scenario === 'aggressive' ? 0.8 :
    0.6;

  const inefficiencies = inefficiencyData.inefficiencies || [];
  const total_inefficiency_cost = inefficiencies.reduce((sum, i) => sum + (i.annual_cost || 50000), 0);

  const annual_benefit = Math.round(
    total_inefficiency_cost *
    scenario_factor *
    config.benefit_realization_factor
  );

  const fte_equivalent = Math.round((annual_benefit / config.avg_fte_cost) * 10) / 10;

  return {
    total_annual: annual_benefit,
    fte_equivalent
  };
}

// ============================================================
// SECTION 6: FINANCIAL METRICS
// ============================================================

function calculateNPV(initial, annual, recurring) {
  let npv = -initial;
  for (let y = 1; y <= config.analysis_years; y++) {
    const cash = annual - recurring;
    npv += cash / Math.pow(1 + config.discount_rate, y);
  }
  return Math.round(npv);
}

function calculateIRR(initial, annual, recurring) {
  const net = annual - recurring;
  if (net <= 0) return 0;
  return Math.round((net / initial) * 100);
}

function calculatePayback(initial, annual, recurring) {
  const net = annual - recurring;
  if (net <= 0) return null;
  return Math.round((initial / net) * 12);
}

// ============================================================
// SECTION 7: BUILD SCENARIO
// ============================================================

function buildScenario(name) {

  const tco = calculateTCO(name);
  const benefits = calculateBenefits(name);

  const npv = calculateNPV(
    tco.implementation_total,
    benefits.total_annual,
    tco.annual_recurring
  );

  const irr = calculateIRR(
    tco.implementation_total,
    benefits.total_annual,
    tco.annual_recurring
  );

  const payback = calculatePayback(
    tco.implementation_total,
    benefits.total_annual,
    tco.annual_recurring
  );

  const fiveYearROI = Math.round(
    ((benefits.total_annual * config.analysis_years - tco.five_year_total) /
    tco.implementation_total) * 100
  );

  return {
    scenario_name: name,
    total_investment: tco.five_year_total,
    annual_benefit: benefits.total_annual,
    npv,
    irr_percentage: irr,
    payback_months: payback,
    five_year_roi: fiveYearROI,
    fte_saved: benefits.fte_equivalent
  };
}

// ============================================================
// SECTION 8: EXECUTION
// ============================================================

const cautious = buildScenario('cautious');
const hybrid = buildScenario('hybrid');
const aggressive = buildScenario('aggressive');

const result = {

  audit_id: resolvedAuditId,
  client_name: resolvedClient,
  analysis_date: new Date().toISOString(),

  recommended_scenario: 'hybrid',

  scenario_comparison: {
    cautious,
    hybrid,
    aggressive
  },

  implementation_cost: hybrid.total_investment,
  annual_saving: hybrid.annual_benefit,
  fte_saved: hybrid.fte_saved,
  efficiency_gain_pct: Math.round(
    (hybrid.annual_benefit /
    (hybrid.annual_benefit + calculateTCO('hybrid').annual_recurring)) * 100
  ),
  three_year_roi: hybrid.five_year_roi,
  payback_period_months: hybrid.payback_months
};

return [{ json: result }];

// Stable Aggregation Node
// No hard dependency on Set Client Config
// Works even if executed mid-workflow

const safeNodeJson = (nodeName) => {
  try {
    if ($(nodeName).isExecuted) {
      return $(nodeName).first().json;
    }
  } catch (e) {}
  return null;
};

const base = $input.first()?.json || {};

// Prefer Optional - Map Queue Row to Config
const dynamicCfg = safeNodeJson("Optional - Map Queue Row to Config");
const setCfg = safeNodeJson("Set Client Config");

const blueprint =
  safeNodeJson("3.1 Generate Target Operating Model") ||
  base.blueprint ||
  {};

const roiData =
  safeNodeJson("3.2 Financial Model Deep-Dive") ||
  base.financial_model ||
  {};

const cfg = {
  ...base,
  ...(dynamicCfg || {}),
  ...(setCfg || {})
};

const clientName =
  cfg.client_name ||
  cfg.client ||
  cfg.organisation_name ||
  "Unknown Client";

const auditId =
  cfg.audit_id ||
  roiData.audit_id ||
  blueprint.audit_id ||
  base.audit_id ||
  "";

return [{
  json: {
    client_name: clientName,
    audit_id: auditId,
    blueprint,
    roi: roiData
  }
}];

const safeNode = (name) => {
  try {
    if ($(name).isExecuted) return $(name).first().json;
  } catch (e) {}
  return null;
};

function parseAIResponse(content) {
  if (!content) return {};
  let cleaned = String(content).trim()
    .replace(/^```json/i, '')
    .replace(/^```/, '')
    .replace(/```$/, '')
    .trim();
  try { return JSON.parse(cleaned); } catch { return {}; }
}

const base = $input.first()?.json || {};
const cfg = safeNode('Set Client Config') || safeNode('Optional - Map Queue Row to Config') || base;
const financialNode = safeNode('3.2 Financial Model Deep-Dive') || {};
const blueprintNode = safeNode('3.1 Generate Target Operating Model') || {};

let blueprint = {};
if (blueprintNode?.message?.content) blueprint = parseAIResponse(blueprintNode.message.content);

let stakeholders = [];
try {
  stakeholders = JSON.parse(cfg.stakeholders_json || '[]');
  if (!Array.isArray(stakeholders)) stakeholders = [];
} catch {
  stakeholders = [];
}

const adkarScores = {
  awareness: Number(cfg.adkar_awareness || 5),
  desire: Number(cfg.adkar_desire || 5),
  knowledge: Number(cfg.adkar_knowledge || 5),
  ability: Number(cfg.adkar_ability || 5),
  reinforcement: Number(cfg.adkar_reinforcement || 5)
};

const adkarOverall = Math.round(
  (adkarScores.awareness + adkarScores.desire + adkarScores.knowledge +
   adkarScores.ability + adkarScores.reinforcement) / 5
);

const readinessLevel =
  adkarOverall >= 7 ? 'Ready' :
  adkarOverall >= 5 ? 'Moderate Risk' : 'High Risk';

const fteSaved =
  financialNode?.scenario_comparison?.hybrid?.fte_saved ||
  financialNode?.scenarios?.hybrid?.fte_saved || 0;

const trainingNeeds = [
  { role: 'AI / Automation Supervisors', headcount: Math.max(Math.ceil(fteSaved * 0.3), 1), training_hours: 40 },
  { role: 'Automation Builders', headcount: Math.max(Math.ceil(fteSaved * 0.2), 1), training_hours: 40 },
  { role: 'Operational Users', headcount: Math.max(Math.ceil(fteSaved), 1), training_hours: 12 }
];

const totalTrainingHours = trainingNeeds.reduce((sum, t) => sum + (t.training_hours * t.headcount), 0);
const hourlyTrainingCost = Number(cfg.training_cost_per_fte || 2500) / 40;
const totalTrainingCost = Math.round(totalTrainingHours * hourlyTrainingCost);

return [{
  json: {
    client_name: cfg.client_name || 'Example Organisation',
    audit_id: cfg.audit_id || '',
    stakeholder_summary: {
      total: stakeholders.length,
      supportive: stakeholders.filter(s => /support|champion/i.test(String(s.current_stance))).length,
      resistant: stakeholders.filter(s => /resist/i.test(String(s.current_stance))).length
    },
    stakeholders,
    adkar_assessment: {
      scores: adkarScores,
      overall_score: adkarOverall,
      readiness_level: readinessLevel
    },
    training_summary: {
      total_hours: totalTrainingHours,
      estimated_cost: totalTrainingCost,
      training_needs: trainingNeeds
    },
    blueprint
  }
}];

