// ===============================
// SAFE NODE ACCESS
// ===============================

function safeNodeJson(nodeName) {
  try {
    const node = $(nodeName);
    if (node && node.isExecuted) {
      return node.first().json || {};
    }
  } catch (e) {}
  return {};
}

function safeContent(nodeName) {
  try {
    const node = $(nodeName);
    if (node && node.isExecuted) {
      return node.first().json?.message?.content || "";
    }
  } catch (e) {}
  return "";
}

function truncate(text, length = 5000) {
  if (!text) return "";
  return String(text).substring(0, length);
}

// ===============================
// FETCH UPSTREAM DATA SAFELY
// ===============================

const clientConfig = safeNodeJson("Set Client Config");
const dataCleaner = safeNodeJson("2.1 Data Cleaner");
const inefficiencyScorer = safeNodeJson("2.2 Inefficiency Scorer - GPT-4o");
const aiFitMapper = safeNodeJson("2.3 Map AI and Automation Opportunities");
const blueprint = safeNodeJson("3.1 Generate Target Operating Model");
const roiSimulator = safeNodeJson("3.2 Financial Model Deep-Dive");

// ===============================
// EXTRACT CONTENT
// ===============================

const inefficiencies = safeContent("2.2 Inefficiency Scorer - GPT-4o");
const recommendations = safeContent("2.3 Map AI and Automation Opportunities");
const blueprintContent = safeContent("3.1 Generate Target Operating Model");

// ===============================
// NORMALISE FINANCIAL STRUCTURE
// ===============================

const scenarios = roiSimulator.scenario_comparison || roiSimulator.scenarios || {};
const hybrid = scenarios.hybrid || {};

const financialTables = roiSimulator.financial_tables || {
  tco_table: "",
  benefits_table: "",
  cashflow_table: "",
  sensitivity_table: ""
};

const assumptions = roiSimulator.assumptions || {};

// ===============================
// BUILD CONTEXT OBJECT
// ===============================

const context = {
  client_name: clientConfig.client_name || dataCleaner.client_name || $json.client_name || "Unknown Client",
  sector: clientConfig.sector || dataCleaner.sector || $json.sector || "Unknown",
  maturity_stage: clientConfig.maturity_stage || $json.maturity_stage || "",
  audit_id: dataCleaner.audit_id || clientConfig.audit_id || $json.audit_id || "",
  audit_date: new Date().toISOString(),

  blueprint_content: truncate(blueprintContent),
  inefficiency_content: truncate(inefficiencies),
  recommendations_content: truncate(recommendations),

  financial_scenarios: scenarios,
  financial_tables: financialTables,
  assumptions: assumptions,

  recommended_scenario: roiSimulator.recommended_scenario || "hybrid",

  hybrid_metrics: {
    three_year_roi: hybrid.three_year_roi || hybrid.five_year_roi || 0,
    npv: hybrid.npv || 0,
    irr: hybrid.irr || 0,
    payback_months: hybrid.payback_months || 0,
    investment: hybrid.investment || hybrid.implementation_cost || 0,
    annual_benefit: hybrid.annual_benefit || hybrid.annual_saving || 0,
    fte_saved: hybrid.fte_saved || 0
  },

  lessons_learned: [
    "AI transformation for " + (clientConfig.sector || "Unknown sector"),
    "Maturity stage: " + (clientConfig.maturity_stage || "Unspecified"),
    "Hybrid ROI: " + (hybrid.three_year_roi || hybrid.five_year_roi || 0) + "%"
  ]
};

// ===============================
// LOG FOR DEBUG
// ===============================

console.log("Executive Summary Context Built:");
console.log("Client:", context.client_name);
console.log("Sector:", context.sector);
console.log("Scenario Keys:", Object.keys(context.financial_scenarios || {}));

// ===============================
// RETURN SINGLE STRUCTURED OBJECT
// ===============================

return [{ json: context }];

const auditId = $('2.1 Data Cleaner').first().json.audit_id;
const blueprintRaw = $('3.1 Generate Target Operating Model').first().json.message.content;

let blueprint;
try {
blueprint = JSON.parse(blueprintRaw);
} catch (e) {
return [
{
json: {
row_key: auditId + '|parse_error',
audit_id: auditId,
process: 'parse_error',
responsible: '',
accountable: '',
consulted: '',
informed: '',
automation_level: '',
tools_used: '',
},
},
];
}

const raci =
Array.isArray(blueprint.new_raci_matrix) ? blueprint.new_raci_matrix :
Array.isArray(blueprint.new_raci) ? blueprint.new_raci :
Array.isArray(blueprint.raci_matrix) ? blueprint.raci_matrix :
Array.isArray(blueprint.raci) ? blueprint.raci :
[];

const toCsvString = (v) => {
if (Array.isArray(v)) return v.filter(Boolean).join(', ');
if (v === null || v === undefined) return '';
return String(v);
};

return raci.map((r, idx) => {
const processCandidate =
r.process ??
r.Process ??
r.process_name ??
r.processName ??
r.process_title ??
r.processTitle ??
r.name ??
r.Name ??
r.activity ??
r.Activity ??
r.workflow ??
r.Workflow ??
r['Process'] ??
r['Process Name'] ??
r['Process_Name'] ??
r['process_name'] ??
r['process'] ??
'unknown_process';

const process =
processCandidate === 'unknown_process'
? ('process_' + (idx + 1))
: String(processCandidate);

const responsible = toCsvString(r.Responsible ?? r.responsible ?? r.R ?? r['R']);
const accountable = toCsvString(r.Accountable ?? r.accountable ?? r.A ?? r['A']);
const consulted = toCsvString(r.Consulted ?? r.consulted ?? r.C ?? r['C']);
const informed = toCsvString(r.Informed ?? r.informed ?? r.I ?? r['I']);

const tools_used = toCsvString(r.tools_used ?? r['Tools Used'] ?? r.tools ?? r['tools']);
const automation_level = toCsvString(r.automation_level ?? r['Automation Level'] ?? r.automation ?? r['automation']);

return {
json: {
row_key: auditId + '|' + process,
audit_id: auditId,
process,
responsible,
accountable,
consulted,
informed,
automation_level,
tools_used,
},
};
});

const safeNodeJson = (nodeName) => {
try {
if ($(nodeName).isExecuted) return $(nodeName).first().json
} catch (e) {}
return null
}

const roiData =
safeNodeJson("3.2 Financial Model Deep-Dive") ||
$input.first().json ||
{}

const blueprint =
safeNodeJson("3.1 Generate Target Operating Model") ||
safeNodeJson("3.1 Blueprint Generator - GPT-4.1mini") ||
{}

const clientConfig =
safeNodeJson("Set Client Config") ||
safeNodeJson("Optional - Map Queue Row to Config") ||
{}

const clientName = clientConfig.client_name || roiData.client_name || "Unknown Client"
const sector = clientConfig.sector || roiData.sector || ""
const auditId = roiData.audit_id || clientConfig.audit_id || ""

const getText = (obj) => {
if (!obj) return ""
if (typeof obj === "string") return obj
if (obj.message && typeof obj.message.content === "string") return obj.message.content
if (typeof obj.content === "string") return obj.content
return ""
}

const blueprintText = getText(blueprint)

const pickNumber = (v) => {
const n = Number(v)
return Number.isFinite(n) ? n : null
}

const hybrid = roiData.scenario_comparison?.hybrid || {}
const cautious = roiData.scenario_comparison?.cautious || {}
const aggressive = roiData.scenario_comparison?.aggressive || {}

const kpiUpdates = {
client_name: clientName,
sector,
audit_id: auditId,
timestamp: new Date().toISOString(),
scenario_recommended: "Hybrid",
scenarios: {
cautious: {
investment: pickNumber(cautious.investment),
annual_benefit: pickNumber(cautious.annual_benefit),
npv: pickNumber(cautious.npv),
irr: pickNumber(cautious.irr),
payback_months: pickNumber(cautious.payback_months),
five_year_roi: pickNumber(cautious.five_year_roi),
fte_saved: pickNumber(cautious.fte_saved)
},
hybrid: {
investment: pickNumber(hybrid.investment),
annual_benefit: pickNumber(hybrid.annual_benefit),
npv: pickNumber(hybrid.npv),
irr: pickNumber(hybrid.irr),
payback_months: pickNumber(hybrid.payback_months),
five_year_roi: pickNumber(hybrid.five_year_roi),
fte_saved: pickNumber(hybrid.fte_saved)
},
aggressive: {
investment: pickNumber(aggressive.investment),
annual_benefit: pickNumber(aggressive.annual_benefit),
npv: pickNumber(aggressive.npv),
irr: pickNumber(aggressive.irr),
payback_months: pickNumber(aggressive.payback_months),
five_year_roi: pickNumber(aggressive.five_year_roi),
fte_saved: pickNumber(aggressive.fte_saved)
}
},
blueprint_available: blueprintText.length > 0
}

return [{ json: kpiUpdates }]

// Generate a plain-text report file (binary) combining Executive Summary + Mermaid Diagrams.
// Designed to work even when 'Set Client Config' is disabled.

const execSummary = $('3.4 Generate Executive Transformation Report').first().json.message?.content || '';
const auditId =
  $('2.1 Data Cleaner').first().json.audit_id ||
  $('Industry Template Selector').first().json.audit_id ||
  $json.audit_id ||
  `AUDIT_${Date.now()}`;

const clientName =
  $('Industry Template Selector').first().json.client_name ||
  $('2.1 Data Cleaner').first().json.client_name ||
  $json.client_name ||
  'Unknown Client';

// Mermaid diagrams (optional)
let diagramsMarkdown = '';
try {
  const diagrams = $('3.3a Mermaid Diagram Generator').first().json;
  if (diagrams && (diagrams.markdown_report || diagrams.mermaid_markdown)) {
    diagramsMarkdown = diagrams.markdown_report || diagrams.mermaid_markdown;
  }
} catch (e) {}

if (!diagramsMarkdown) {
  diagramsMarkdown = '## Mermaid Diagrams\n\n*Diagrams not available*\n';
}

const content = `${clientName} - AI Operating Model Transformation
Executive Summary & Transformation Roadmap
Generated: ${new Date().toLocaleString()}
Audit ID: ${auditId}

${'='.repeat(80)}

${execSummary}

${'='.repeat(80)}

${diagramsMarkdown}

${'='.repeat(80)}

Confidential | Internal Simulation Output
Powered by n8n
`;

return [{
  json: {
    client_name: clientName,
    audit_id: auditId,
    report_text: content,
    has_diagrams: diagramsMarkdown.length > 50
  },
  binary: {
    data: {
      data: Buffer.from(content, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: `${clientName.replace(/[^a-z0-9]+/gi,'_')}_AI_Operating_Model_${auditId}.txt`
    }
  }
}];

// Extract Recommendations from AI Fit Mapper (stable, no hard dependency)
// Safe parsing + safe fallbacks + no required node execution order

function parseAIResponse(content) {
  if (!content) return { recommendations: [] };

  let cleaned = content.trim();

  if (cleaned.startsWith('```json')) cleaned = cleaned.slice(7);
  else if (cleaned.startsWith('```')) cleaned = cleaned.slice(3);

  if (cleaned.endsWith('```')) cleaned = cleaned.slice(0, -3);

  cleaned = cleaned.trim();

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    return { recommendations: [] };
  }
}

const base = $input.first()?.json || {};
let recommendationsData = { recommendations: [] };

// Safe AI Fit Mapper read
try {
  if ($("2.3 Map AI and Automation Opportunities").isExecuted) {
    const nodeData = $("2.3 Map AI and Automation Opportunities").first().json;
    const content = nodeData.message?.content || '';
    recommendationsData = parseAIResponse(content);
  }
} catch (e) {}

// Safe client + audit resolution (no hard dependency)
let clientConfig = { ...base };

try {
  if ($("Optional - Map Queue Row to Config").isExecuted) {
    clientConfig = {
      ...clientConfig,
      ...$("Optional - Map Queue Row to Config").first().json
    };
  }
} catch (e) {}

try {
  if ($("Set Client Config").isExecuted) {
    clientConfig = {
      ...clientConfig,
      ...$("Set Client Config").first().json
    };
  }
} catch (e) {}

let auditData = { ...base };
try {
  if ($("2.1 Data Cleaner").isExecuted) {
    auditData = {
      ...auditData,
      ...$("2.1 Data Cleaner").first().json
    };
  }
} catch (e) {}

const clientName =
  clientConfig.client_name ||
  auditData.client_name ||
  base.client_name ||
  "Unknown Client";

const auditId =
  clientConfig.audit_id ||
  auditData.audit_id ||
  base.audit_id ||
  "N/A";

const recommendations = recommendationsData.recommendations || [];

if (recommendations.length === 0) {
  return [{
    json: {
      Audit_ID: auditId,
      Client_Name: clientName,
      Process: "No recommendations generated",
      AI_Fit: "N/A",
      Recommended_Tech: "N/A",
      Complexity: "N/A",
      Potential_Saving_Pct: 0,
      ROI_Months: 0,
      Description: "AI output did not contain structured recommendations"
    }
  }];
}

// Format for Google Sheets
const formattedRecommendations = recommendations.map(rec => ({
  Audit_ID: auditId,
  Client_Name: clientName,
  Process: rec.process || "",
  AI_Fit: rec.ai_fit || "Medium",
  Recommended_Tech: Array.isArray(rec.recommended_tech)
    ? rec.recommended_tech.join(", ")
    : rec.recommended_tech || "",
  Complexity: rec.implementation_complexity || "Moderate",
  Potential_Saving_Pct: Number(rec.potential_saving_pct) || 0,
  ROI_Months: Number(rec.estimated_roi_months) || 12,
  Description: rec.description || ""
}));

return formattedRecommendations.map(r => ({ json: r }));

// OPTIONAL QUEUE PATH
// Maps a row from the optional Clients_Queue Google Sheet into the same
// configuration contract used by the manual "Set Client Config" node.

const row = $input.first()?.json || {};
const pick = (...keys) => {
  for (const key of keys) {
    const value = row[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return null;
};

const clientName = pick('client_name', 'Client Name') || 'Example Organisation';
const compact = new Date().toISOString().replace(/[:.]/g, '').slice(0, 15);
const clientId = String(clientName).replace(/\s+/g, '_').replace(/[^A-Za-z0-9_]/g, '').slice(0, 40) || 'CLIENT';

return [{
  json: {
    client_name: clientName,
    notification_email: pick('notification_email', 'Notification Email') || 'YOUR_NOTIFICATION_EMAIL',
    sector: pick('sector', 'Sector') || 'Marketing & Creative Production',
    maturity_stage: pick('maturity_stage', 'Maturity Stage') || 'Walk',
    market_count: Number(pick('market_count', 'Market Count') || 5),

    org_drive_file_id: pick('org_drive_file_id', 'Org Drive File ID') || 'YOUR_ORG_DOCUMENT_FILE_ID',
    master_sheet_id: pick('master_sheet_id', 'Master Sheet ID') || 'YOUR_MASTER_GOOGLE_SHEET_ID',
    output_drive_folder_id: pick('output_drive_folder_id', 'Output Drive Folder ID') || 'YOUR_OUTPUT_DRIVE_FOLDER_ID',
    slack_channel_id: pick('slack_channel_id', 'Slack Channel ID') || 'YOUR_SLACK_CHANNEL_ID',

    avg_fte_cost: Number(pick('avg_fte_cost') || 85000),
    hours_per_fte_year: Number(pick('hours_per_fte_year') || 1800),
    software_license_annual: Number(pick('software_license_annual') || 25000),
    integration_cost_per_system: Number(pick('integration_cost_per_system') || 15000),
    training_cost_per_fte: Number(pick('training_cost_per_fte') || 2500),
    change_management_pct: Number(pick('change_management_pct') || 0.15),
    discount_rate: Number(pick('discount_rate') || 0.10),
    implementation_risk_buffer: Number(pick('implementation_risk_buffer') || 0.20),
    benefit_realization_factor: Number(pick('benefit_realization_factor') || 0.85),
    analysis_years: Number(pick('analysis_years') || 5),

    adkar_awareness: Number(pick('adkar_awareness') || 5),
    adkar_desire: Number(pick('adkar_desire') || 5),
    adkar_knowledge: Number(pick('adkar_knowledge') || 5),
    adkar_ability: Number(pick('adkar_ability') || 5),
    adkar_reinforcement: Number(pick('adkar_reinforcement') || 5),
    stakeholders_json: pick('stakeholders_json') || '[]',

    audit_id: pick('audit_id', 'Audit ID') || `AUDIT_${clientId}_${compact}`,
    audit_timestamp: new Date().toISOString(),
    trigger_source: 'google_sheets_queue'
  }
}];

// Community-safe Industry Guidance Selector
// This node provides qualitative sector guidance only.
// Quantitative benchmark values must come from the user's "Benchmarks" sheet.

const cfg = $input.first().json || {};
const sector = cfg.sector || 'Marketing & Creative Production';

const templates = {
  'Marketing & Creative Production': {
    sector_code: 'MKT',
    key_kpis: ['turnaround_time', 'utilization', 'cost_per_asset', 'error_rate', 'volume', 'client_satisfaction'],
    common_inefficiencies: ['manual adaptation', 'review bottlenecks', 'tool fragmentation', 'manual localisation', 'asset-routing delays'],
    ai_solutions: ['content generation and adaptation', 'translation/localisation assistance', 'brand compliance checks', 'workflow orchestration', 'asset routing'],
    compliance: ['brand governance', 'privacy', 'accessibility'],
    analysis_context: 'Focus on production efficiency, asset lifecycle, review and approval, localisation, and team utilisation.'
  },
  'Retail': {
    sector_code: 'RTL',
    key_kpis: ['inventory_turnover', 'fulfilment_time', 'return_rate', 'conversion', 'supply_chain_efficiency'],
    common_inefficiencies: ['manual inventory updates', 'channel fragmentation', 'pricing updates', 'returns processing', 'forecasting gaps'],
    ai_solutions: ['demand forecasting', 'inventory optimisation', 'dynamic pricing support', 'customer service automation', 'personalisation'],
    compliance: ['privacy', 'payment security', 'consumer protection'],
    analysis_context: 'Focus on omnichannel operations, inventory, fulfilment, customer service and supply-chain visibility.'
  },
  'Financial Services': {
    sector_code: 'FIN',
    key_kpis: ['processing_time', 'straight_through_processing', 'error_rate', 'compliance_rate', 'cost_per_case'],
    common_inefficiencies: ['manual document processing', 'compliance bottlenecks', 'legacy integration', 'manual review', 'slow onboarding'],
    ai_solutions: ['document processing', 'risk triage', 'fraud detection support', 'workflow orchestration', 'regulatory reporting automation'],
    compliance: ['privacy', 'financial regulation', 'auditability', 'model governance'],
    analysis_context: 'Focus on controls, audit trails, risk, document-heavy processes and straight-through processing.'
  },
  'Healthcare': {
    sector_code: 'HLC',
    key_kpis: ['throughput', 'documentation_time', 'error_rate', 'claims_time', 'service_quality'],
    common_inefficiencies: ['manual documentation', 'system fragmentation', 'claims processing', 'scheduling', 'paper-based workflows'],
    ai_solutions: ['documentation assistance', 'workflow orchestration', 'scheduling support', 'claims automation', 'knowledge retrieval'],
    compliance: ['privacy', 'clinical safety', 'auditability', 'human oversight'],
    analysis_context: 'Focus on safe workflow improvement, documentation, scheduling, interoperability and human review.'
  },
  'Manufacturing': {
    sector_code: 'MFG',
    key_kpis: ['oee', 'defect_rate', 'cycle_time', 'downtime', 'lead_time'],
    common_inefficiencies: ['reactive maintenance', 'manual inspection', 'planning gaps', 'paper work instructions', 'supply-chain visibility'],
    ai_solutions: ['predictive maintenance', 'vision-assisted quality checks', 'planning support', 'workflow orchestration', 'knowledge assistance'],
    compliance: ['quality', 'safety', 'environmental controls', 'traceability'],
    analysis_context: 'Focus on production flow, maintenance, quality, planning, traceability and safe automation.'
  },
  'Technology': {
    sector_code: 'TECH',
    key_kpis: ['deployment_frequency', 'lead_time', 'mttr', 'change_failure_rate', 'support_resolution_time'],
    common_inefficiencies: ['manual testing', 'deployment friction', 'documentation gaps', 'support repetition', 'review bottlenecks'],
    ai_solutions: ['coding assistance', 'testing automation', 'AIOps', 'support automation', 'documentation generation'],
    compliance: ['security', 'privacy', 'change control', 'access governance'],
    analysis_context: 'Focus on delivery flow, reliability, support, documentation, security and developer productivity.'
  }
};

const template = templates[sector] || templates['Marketing & Creative Production'];

return [{
  json: {
    ...cfg,
    sector_code: template.sector_code,
    sector_kpis: template.key_kpis,
    sector_inefficiencies: template.common_inefficiencies,
    sector_ai_solutions: template.ai_solutions,
    sector_compliance: template.compliance,
    sector_analysis_context: template.analysis_context,
    sector_benchmarks: {},
    benchmark_source: 'User-provided Benchmarks sheet'
  }
