function safeString(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  try { return JSON.stringify(v); } catch (e) { return String(v); }
}

function stripCodeFences(text) {
  return text
    .replace(/```json\s*/gi, "")
    .replace(/```mermaid\s*/gi, "")
    .replace(/```/g, "")
    .trim();
}

function extractFirstJsonObject(text) {
  // Attempts to locate the first valid JSON object or array in a messy string.
  const s = text.trim();
  if (!s) return null;

  // Quick path
  if ((s.startsWith("{") && s.endsWith("}")) || (s.startsWith("[") && s.endsWith("]"))) {
    return s;
  }

  // Scan for balanced braces/brackets
  const startIdx = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === "{" || ch === "[") startIdx.push(i);
  }
  for (const start of startIdx) {
    const open = s[start];
    const close = open === "{" ? "}" : "]";
    let depth = 0;
    for (let j = start; j < s.length; j++) {
      const c = s[j];
      if (c === open) depth++;
      if (c === close) depth--;
      if (depth === 0) {
        return s.slice(start, j + 1);
      }
    }
  }
  return null;
}

function safeParseJson(maybeJsonText) {
  const cleaned = stripCodeFences(safeString(maybeJsonText));
  const candidate = extractFirstJsonObject(cleaned);
  if (!candidate) return null;
  try {
    return JSON.parse(candidate);
  } catch (e) {
    return null;
  }
}

function sanitizeMermaid(code) {
  const t = stripCodeFences(safeString(code));

  // Remove any stray leading/trailing junk lines
  const lines = t.split(/\r?\n/).map(l => l.trimEnd());

  // Filter out empty leading lines
  while (lines.length && !lines[0].trim()) lines.shift();
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();

  return lines.join("\n").trim();
}

function buildFallbackMermaid(auditId, clientName) {
  const title = clientName ? clientName : "Client";
  const id = auditId ? auditId : "audit";
  return `
flowchart TB
  A["Intake and Brief"] --> B["Triage and Validate"]
  B --> C["Design Operating Model"]
  C --> D["RACI and Governance"]
  D --> E["Outputs and Reporting"]
  E --> F["Store in Google Sheets"]
  subgraph Meta
    M1["audit_id: ${id}"]
    M2["client_name: ${title}"]
  end
`.trim();
}

