if (!mermaid_code) {
  mermaid_code = buildFallbackMermaid(audit_id, client_name);
} else {
  // Ensure it starts with a mermaid header if it looks like raw nodes
  const startsOk =
    mermaid_code.startsWith("flowchart") ||
    mermaid_code.startsWith("sequenceDiagram") ||
