function stripFences(t) {
  return String(t || '').replace(/```json\s*|```/g, '').trim();
}

function tryParseJson(text) {
  const cleaned = stripFences(text);
  try { return JSON.parse(cleaned); } catch (e) { return null; }
}

function extractSection(md, heading) {
  const src = String(md || '');
  const idx = src.indexOf(heading);
  if (idx === -1) return '';
  const rest = src.slice(idx);
  // stop at next "## " heading
  const next = rest.slice(heading.length).search(/\n##\s+/);
  if (next === -1) return rest.trim();
  return rest.slice(0, heading.length + next).trim();
}

function extractTable(md, heading) {
  const section = extractSection(md, heading);
  const lines = section.split('\n');
  const tableLines = [];
  let started = false;
  for (const line of lines) {
    if (line.includes('|') && line.trim().startsWith('|')) {
      started = true;
      tableLines.push(line);
      continue;
    }
    if (started && (!line.trim() || !line.includes('|'))) break;
  }
  return tableLines.join('\n').trim();
}

