function safeGet(nodeName) {
  try {
    const n = $(nodeName);
    return (n && n.isExecuted) ? (n.first().json || null) : null;
  } catch (e) { return null; }
}
function safeContent(nodeName) {
  try {
    const n = $(nodeName);
    if (!n || !n.isExecuted) return '';
    const j = n.first().json;
    return j.message?.content || j.text || j.content || j.output || '';
  } catch (e) { return ''; }
}
function safeAll(nodeName) {
  try {
    const n = $(nodeName);
    return (n && n.isExecuted) ? n.all().map(i => i.json) : [];
  } catch (e) { return []; }
}
function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v !== null && v !== undefined && v !== '' && v !== '[Diagram not generated...]') return v;
  }
  return '';
}
function str(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  return '';
}
function safeNum(v) {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string' && v.trim() === '') return '';
  const n = Number(v);
  return Number.isFinite(n) ? n : '';
}
function extractSection(text, ...headings) {
  if (!text) return '';
  for (const h of headings) {
    const re = new RegExp('##?\\s+' + h + '[\\s\\S]*?(?=##|$)', 'i');
    const m = text.match(re);
    if (m) return m[0].replace(/^##?\\s+[^\\n]*\\n?/, '').trim();
  }
  return '';
}

